#include "mtie/transformer.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <limits>
#include <numeric>
#include <sstream>
#include <stdexcept>

namespace mtie {
namespace { constexpr char magic[]="MTIEWEIGHT"; constexpr char tokmagic[]="MTIETOK1";
void require(bool b,const std::string& s){if(!b) throw std::runtime_error(s);}
template<class T> void raw_write(std::ofstream& f,const T& x){f.write(reinterpret_cast<const char*>(&x),sizeof x);}
template<class T> void raw_read(std::ifstream& f,T& x){f.read(reinterpret_cast<char*>(&x),sizeof x); require(bool(f),"truncated weight file");}
void write_tensor(std::ofstream& f,const Tensor& t){uint64_t n=t.data.size();raw_write(f,n);f.write(reinterpret_cast<const char*>(t.data.data()),n*sizeof(float));}
Tensor read_tensor(std::ifstream& f,size_t r,size_t c){uint64_t n;raw_read(f,n);require(n==r*c,"weight tensor has incompatible shape");Tensor t(r,c);f.read(reinterpret_cast<char*>(t.data.data()),n*sizeof(float));require(bool(f),"truncated tensor data");return t;}
void write_vec(std::ofstream& f,const std::vector<float>& v){uint64_t n=v.size();raw_write(f,n);f.write(reinterpret_cast<const char*>(v.data()),n*sizeof(float));}
std::vector<float> read_vec(std::ifstream& f,size_t n){uint64_t actual;raw_read(f,actual);require(actual==n,"weight vector has incompatible shape");std::vector<float> x(n);f.read(reinterpret_cast<char*>(x.data()),n*sizeof(float));require(bool(f),"truncated vector data");return x;}
std::vector<float> matvec(const Tensor& m,const std::vector<float>& x){require(m.cols==x.size(),"internal matrix shape mismatch");std::vector<float> y(m.rows);for(size_t i=0;i<m.rows;++i)for(size_t j=0;j<m.cols;++j)y[i]+=m(i,j)*x[j];return y;}
void add(std::vector<float>& a,const std::vector<float>& b){for(size_t i=0;i<a.size();++i)a[i]+=b[i];}
} 
size_t ModelWeights::parameter_count() const { size_t n=token_embedding.data.size()+position_embedding.data.size()+final_projection.data.size()+final_ln_g.size()+final_ln_b.size();for(auto& l:layers)n+=l.wq.data.size()+l.wk.data.size()+l.wv.data.size()+l.wo.data.size()+l.w1.data.size()+l.w2.data.size()+l.ln1_g.size()+l.ln1_b.size()+l.ln2_g.size()+l.ln2_b.size();return n;}
size_t ModelWeights::bytes() const{return parameter_count()*sizeof(float);}
std::vector<float> stable_softmax(const std::vector<float>& x){require(!x.empty(),"softmax needs values");float m=*std::max_element(x.begin(),x.end());std::vector<float> y(x.size());double sum=0;for(size_t i=0;i<x.size();++i){y[i]=std::exp(x[i]-m);sum+=y[i];}for(float& v:y)v=float(v/sum);return y;}
void layer_norm(std::vector<float>& x,const std::vector<float>& g,const std::vector<float>& b){require(x.size()==g.size()&&x.size()==b.size(),"layer norm shape mismatch");double mean=std::accumulate(x.begin(),x.end(),0.0)/x.size(),var=0;for(float v:x)var+=(v-mean)*(v-mean);float inv=1.0f/std::sqrt(float(var/x.size())+1e-5f);for(size_t i=0;i<x.size();++i)x[i]=(x[i]-float(mean))*inv*g[i]+b[i];}
void save_weights(const ModelWeights& w,const std::filesystem::path& p){std::ofstream f(p,std::ios::binary);require(bool(f),"cannot write weight file: "+p.string());f.write(magic,sizeof magic);raw_write(f,kFormatVersion);raw_write(f,w.config);write_tensor(f,w.token_embedding);write_tensor(f,w.position_embedding);for(auto& l:w.layers){write_tensor(f,l.wq);write_tensor(f,l.wk);write_tensor(f,l.wv);write_tensor(f,l.wo);write_tensor(f,l.w1);write_tensor(f,l.w2);write_vec(f,l.ln1_g);write_vec(f,l.ln1_b);write_vec(f,l.ln2_g);write_vec(f,l.ln2_b);}write_vec(f,w.final_ln_g);write_vec(f,w.final_ln_b);write_tensor(f,w.final_projection);}
ModelWeights load_weights(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);require(bool(f),"cannot open weight file: "+p.string());char m[sizeof magic];f.read(m,sizeof m);require(bool(f)&&std::equal(std::begin(m),std::end(m),magic),"not an MTIE weight file");uint32_t ver;raw_read(f,ver);require(ver==kFormatVersion,"unsupported weight format version");ModelWeights w;raw_read(f,w.config);auto c=w.config;require(c.vocab_size&&c.d_model&&c.n_heads&&c.n_layers&&c.ff_dim&&c.max_seq_len&&c.d_model%c.n_heads==0,"invalid model config");w.token_embedding=read_tensor(f,c.vocab_size,c.d_model);w.position_embedding=read_tensor(f,c.max_seq_len,c.d_model);for(uint32_t i=0;i<c.n_layers;++i){LayerWeights l;l.wq=read_tensor(f,c.d_model,c.d_model);l.wk=read_tensor(f,c.d_model,c.d_model);l.wv=read_tensor(f,c.d_model,c.d_model);l.wo=read_tensor(f,c.d_model,c.d_model);l.w1=read_tensor(f,c.ff_dim,c.d_model);l.w2=read_tensor(f,c.d_model,c.ff_dim);l.ln1_g=read_vec(f,c.d_model);l.ln1_b=read_vec(f,c.d_model);l.ln2_g=read_vec(f,c.d_model);l.ln2_b=read_vec(f,c.d_model);w.layers.push_back(std::move(l));}w.final_ln_g=read_vec(f,c.d_model);w.final_ln_b=read_vec(f,c.d_model);w.final_projection=read_tensor(f,c.vocab_size,c.d_model);return w;}
Tokenizer Tokenizer::load(const std::filesystem::path& p){std::ifstream f(p);require(bool(f),"cannot open tokenizer: "+p.string());std::string h;std::getline(f,h);require(h==tokmagic,"unsupported tokenizer format");Tokenizer t;std::string s;while(std::getline(f,s))if(!s.empty())t.tokens.push_back(s);require(!t.tokens.empty(),"tokenizer contains no tokens");return t;}
void Tokenizer::save(const std::filesystem::path& p) const {std::ofstream f(p);require(bool(f),"cannot write tokenizer: "+p.string());f<<tokmagic<<'\n';for(auto& s:tokens)f<<s<<'\n';}
std::vector<uint32_t> Tokenizer::encode(const std::string& text) const {std::vector<uint32_t> r;for(unsigned char ch:text){std::string s(1,char(ch));auto it=std::find(tokens.begin(),tokens.end(),s);r.push_back(it==tokens.end()?unk_id:uint32_t(it-tokens.begin()));}return r;}
std::string Tokenizer::decode(const std::vector<uint32_t>& ids) const {std::string out;for(auto id:ids)out+=id<tokens.size()?tokens[id]:"?";return out;}
Tokenizer make_demo_tokenizer(){Tokenizer t;t.tokens={"?"," ","a","b","c","d","e","h","i","l","o","r","t","w","!","."};return t;}
ModelWeights make_deterministic_demo(){ModelWeights w;w.config={16,16,4,2,32,64};auto c=w.config;std::mt19937 rng(1337);std::normal_distribution<float> d(0,.08f);auto init=[&](Tensor& t){for(auto& x:t.data)x=d(rng);};w.token_embedding=Tensor(c.vocab_size,c.d_model);w.position_embedding=Tensor(c.max_seq_len,c.d_model);init(w.token_embedding);init(w.position_embedding);for(uint32_t n=0;n<c.n_layers;++n){LayerWeights l;l.wq=Tensor(c.d_model,c.d_model);l.wk=Tensor(c.d_model,c.d_model);l.wv=Tensor(c.d_model,c.d_model);l.wo=Tensor(c.d_model,c.d_model);l.w1=Tensor(c.ff_dim,c.d_model);l.w2=Tensor(c.d_model,c.ff_dim);init(l.wq);init(l.wk);init(l.wv);init(l.wo);init(l.w1);init(l.w2);l.ln1_g.assign(c.d_model,1);l.ln1_b.assign(c.d_model,0);l.ln2_g.assign(c.d_model,1);l.ln2_b.assign(c.d_model,0);w.layers.push_back(std::move(l));}w.final_ln_g.assign(c.d_model,1);w.final_ln_b.assign(c.d_model,0);w.final_projection=Tensor(c.vocab_size,c.d_model);init(w.final_projection);return w;}
Transformer::Transformer(ModelWeights w):w_(std::move(w)){require(w_.layers.size()==w_.config.n_layers,"layer count incompatible with config");}
std::vector<float> Transformer::logits(const std::vector<uint32_t>& ids) const {auto c=w_.config;require(!ids.empty()&&ids.size()<=c.max_seq_len,"prompt length must be 1..max_seq_len");for(auto id:ids)require(id<c.vocab_size,"token id outside vocabulary");size_t T=ids.size(),D=c.d_model,H=c.n_heads,dh=D/H;std::vector<std::vector<float>> x(T,std::vector<float>(D));for(size_t t=0;t<T;++t)for(size_t j=0;j<D;++j)x[t][j]=w_.token_embedding(ids[t],j)+w_.position_embedding(t,j);for(const auto& l:w_.layers){auto z=x;std::vector<std::vector<float>> q(T),k(T),v(T),a(T,std::vector<float>(D));for(auto& e:z)layer_norm(e,l.ln1_g,l.ln1_b);for(size_t t=0;t<T;++t){q[t]=matvec(l.wq,z[t]);k[t]=matvec(l.wk,z[t]);v[t]=matvec(l.wv,z[t]);}for(size_t t=0;t<T;++t)for(size_t h=0;h<H;++h){std::vector<float>s(t+1);for(size_t u=0;u<=t;++u)for(size_t j=0;j<dh;++j)s[u]+=q[t][h*dh+j]*k[u][h*dh+j];for(auto& e:s)e/=std::sqrt(float(dh));auto p=stable_softmax(s);for(size_t u=0;u<=t;++u)for(size_t j=0;j<dh;++j)a[t][h*dh+j]+=p[u]*v[u][h*dh+j];}for(size_t t=0;t<T;++t)add(x[t],matvec(l.wo,a[t]));z=x;for(auto& e:z)layer_norm(e,l.ln2_g,l.ln2_b);for(size_t t=0;t<T;++t){auto h=matvec(l.w1,z[t]);for(auto& e:h)e=std::max(0.f,e);add(x[t],matvec(l.w2,h));}}auto last=x.back();layer_norm(last,w_.final_ln_g,w_.final_ln_b);return matvec(w_.final_projection,last);}
uint32_t sample(const std::vector<float>& x,float temp,int top_k,std::mt19937_64& rng){require(temp>=0,"temperature must be non-negative");if(temp==0)return uint32_t(std::max_element(x.begin(),x.end())-x.begin());std::vector<size_t> i(x.size());std::iota(i.begin(),i.end(),0);if(top_k>0&&size_t(top_k)<i.size()){std::partial_sort(i.begin(),i.begin()+top_k,i.end(),[&](auto a,auto b){return x[a]>x[b];});i.resize(top_k);}std::vector<float> v;for(auto n:i)v.push_back(x[n]/temp);auto p=stable_softmax(v);std::discrete_distribution<size_t>d(p.begin(),p.end());return uint32_t(i[d(rng)]);}
std::vector<uint32_t> Transformer::generate(std::vector<uint32_t> p,size_t n,float temp,int top_k,uint64_t seed,std::vector<double>* times) const {std::mt19937_64 rng(seed);for(size_t j=0;j<n&&p.size()<w_.config.max_seq_len;++j){auto a=std::chrono::steady_clock::now();p.push_back(sample(logits(p),temp,top_k,rng));auto b=std::chrono::steady_clock::now();if(times)times->push_back(std::chrono::duration<double,std::milli>(b-a).count());}return p;}
} // namespace mtie
